window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-87a8b583b88e47d7"]={"versions": [{"id": "FIG-87a8b583b88e47d7", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Prüfschritts <code>E2E_P01_process_counter</code> innerhalb des AUTOSAR E2E Profile 1 (E2E Protocol). Das Diagramm modelliert die algorithmische Auswertung und Differenzberechnung des zyklischen Zählers (Counter) bei empfangenen Daten mit gültiger CRC zur Erkennung von Datenwiederholungen, Paketverlusten oder Sequenzfehlern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Start- und Endknoten</strong>: Initialer Knoten (Start) sowie finaler Ablaufknoten (<code>return</code>).\n</li><li><strong>Verzweigungs- und Zusammenführungsknoten (Decision/Merge Nodes)</strong>: Rauten zur Verzweigung anhand von Counter-Bedingungen und Zusammenführung der Kontrollflusspfade.\n</li><li><strong>Zustands- und Konfigurationsvariablen</strong>:\n<ul class=\"fig-list\"><li><code>ReceivedCounter</code>: Zählerwert der aktuell empfangenen Botschaft.\n</li><li><code>State-&gt;LastValidCounter</code>: Zuletzt gültig empfangener Zählerwert im Zustandsvektor.\n</li><li><code>DeltaCounter</code>: Berechnete Zählerdifferenz unter Berücksichtigung des Modulo-15-Überlaufs.\n</li><li><code>State-&gt;MaxDeltaCounter</code>: Maximal zulässige Zählerdifferenz (Schwellwert für Sequenzfehler).\n</li><li><code>returnvalue</code>: Rückgabewert des Prüfschritts (<code>E2E_P01STATUS_REPEATED</code>, <code>E2E_P01STATUS_WRONGSEQUENCE</code> oder das Ergebnis nachfolgender Unterfunktionen).\n</li></ul>\n</li><li><strong>Untergeordnete Aktionen / Funktionsaufrufe (Subactivity Actions)</strong>:\n<ul class=\"fig-list\"><li><code>E2E_P01_process_NoNewOrRepeatedDataCounter</code>\n</li><li><code>E2E_P01_handle_wrongSequence</code>\n</li><li><code>returnvalue = E2E_P01_handle_ok_and_okSomeLost</code>\n</li></ul>\n</li><li><strong>Kommentare / Notizen</strong>:\n<ul class=\"fig-list\"><li>„Compute the delta, taking into account the overflow.“\n</li><li>„The previous and the current data have correct CRC, verify the counter.“\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Delta-Berechnung mit Überlaufbehandlung</strong>:\n<ul class=\"fig-list\"><li>Prüfung, ob <code>ReceivedCounter &gt;= State-&gt;LastValidCounter</code>.\n</li><li>Wenn wahr: <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code>.\n</li><li>Wenn falsch (Überlauf des 4-Bit-Zählers): <code>DeltaCounter = 15 + ReceivedCounter - State-&gt;LastValidCounter</code>.\n</li><li>Zusammenführung der beiden Zweige.\n</li></ul>\n</li><li><strong>Plausibilitätsprüfung des Zählers</strong>:\n<ul class=\"fig-list\"><li>Prüfung, ob <code>DeltaCounter == 0</code>:\n<ul class=\"fig-list\"><li>Wenn <code>[TRUE]</code>: Aufruf der Unterfunktion <code>E2E_P01_process_NoNewOrRepeatedDataCounter</code>, anschließende Zuweisung <code>returnvalue = E2E_P01STATUS_REPEATED</code> und Verzweigung zum Ende (<code>return</code>).\n</li><li>Wenn <code>[FALSE]</code>: Weiterleitung zur nächsten Verzweigung.\n</li></ul>\n</li><li>Prüfung, ob <code>DeltaCounter &gt; State-&gt;MaxDeltaCounter</code>:\n<ul class=\"fig-list\"><li>Wenn <code>[TRUE]</code>: Aufruf der Unterfunktion <code>E2E_P01_handle_wrongSequence</code>, anschließende Zuweisung <code>returnvalue = E2E_P01STATUS_WRONGSEQUENCE</code> und Verzweigung zum Ende (<code>return</code>).\n</li><li>Wenn <code>[FALSE]</code>: Ausführung von <code>returnvalue = E2E_P01_handle_ok_and_okSomeLost</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Abschluss</strong>: Alle Pfade werden zusammengeführt und die Aktivität terminiert mit <code>return</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Auswerteverhalten für E2E Profile 1 Empfänger gemäß AUTOSAR PRS E2EProtocol. Software-Entwickler müssen sicherstellen, dass bei der Counter-Arithmetik der Wertebereich (4 Bit, Zyklus 0 bis 14) exakt mit der Offset-Korrektur <code>15 + ReceivedCounter - LastValidCounter</code> abgebildet wird. Die Unterfunktionen zur Zählerfortschreibung bei wiederholten Daten bzw. Sequenzfehlern müssen vor dem Setzen des jeweiligen Return-Status ausgeführt werden. Treten keine Wiederholungen oder übermäßigen Sprünge auf, ist zwingend die Routine <code>E2E_P01_handle_ok_and_okSomeLost</code> zur Auswertung regulärer bzw. verlustbehafteter Datenübertragungen zu durchlaufen.</p>"}, {"id": "FIG-006103441fa3be3a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Prüfschritts <code>E2E_P01_process_counter</code> innerhalb des AUTOSAR E2E Profile 1 (E2E Protocol). Das Diagramm modelliert die algorithmische Auswertung und Differenzberechnung des zyklischen Zählers (Counter) bei empfangenen Daten mit gültiger CRC zur Erkennung von Datenwiederholungen, Paketverlusten oder Sequenzfehlern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Start- und Endknoten</strong>: Initialer Knoten (Start) sowie finaler Ablaufknoten (<code>return</code>).\n</li><li><strong>Verzweigungs- und Zusammenführungsknoten (Decision/Merge Nodes)</strong>: Rauten zur Verzweigung anhand von Counter-Bedingungen und Zusammenführung der Kontrollflusspfade.\n</li><li><strong>Zustands- und Konfigurationsvariablen</strong>:\n<ul class=\"fig-list\"><li><code>ReceivedCounter</code>: Zählerwert der aktuell empfangenen Botschaft.\n</li><li><code>State-&gt;LastValidCounter</code>: Zuletzt gültig empfangener Zählerwert im Zustandsvektor.\n</li><li><code>DeltaCounter</code>: Berechnete Zählerdifferenz unter Berücksichtigung des Modulo-15-Überlaufs.\n</li><li><code>State-&gt;MaxDeltaCounter</code>: Maximal zulässige Zählerdifferenz (Schwellwert für Sequenzfehler).\n</li><li><code>returnvalue</code>: Rückgabewert des Prüfschritts (<code>E2E_P01STATUS_REPEATED</code>, <code>E2E_P01STATUS_WRONGSEQUENCE</code> oder das Ergebnis nachfolgender Unterfunktionen).\n</li></ul>\n</li><li><strong>Untergeordnete Aktionen / Funktionsaufrufe (Subactivity Actions)</strong>:\n<ul class=\"fig-list\"><li><code>E2E_P01_process_NoNewOrRepeatedDataCounter</code>\n</li><li><code>E2E_P01_handle_wrongSequence</code>\n</li><li><code>returnvalue = E2E_P01_handle_ok_and_okSomeLost</code>\n</li></ul>\n</li><li><strong>Kommentare / Notizen</strong>:\n<ul class=\"fig-list\"><li>„Compute the delta, taking into account the overflow.“\n</li><li>„The previous and the current data have correct CRC, verify the counter.“\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Delta-Berechnung mit Überlaufbehandlung</strong>:\n<ul class=\"fig-list\"><li>Prüfung, ob <code>ReceivedCounter &gt;= State-&gt;LastValidCounter</code>.\n</li><li>Wenn wahr: <code>DeltaCounter = ReceivedCounter - State-&gt;LastValidCounter</code>.\n</li><li>Wenn falsch (Überlauf des 4-Bit-Zählers): <code>DeltaCounter = 15 + ReceivedCounter - State-&gt;LastValidCounter</code>.\n</li><li>Zusammenführung der beiden Zweige.\n</li></ul>\n</li><li><strong>Plausibilitätsprüfung des Zählers</strong>:\n<ul class=\"fig-list\"><li>Prüfung, ob <code>DeltaCounter == 0</code>:\n<ul class=\"fig-list\"><li>Wenn <code>[TRUE]</code>: Aufruf der Unterfunktion <code>E2E_P01_process_NoNewOrRepeatedDataCounter</code>, anschließende Zuweisung <code>returnvalue = E2E_P01STATUS_REPEATED</code> und Verzweigung zum Ende (<code>return</code>).\n</li><li>Wenn <code>[FALSE]</code>: Weiterleitung zur nächsten Verzweigung.\n</li></ul>\n</li><li>Prüfung, ob <code>DeltaCounter &gt; State-&gt;MaxDeltaCounter</code>:\n<ul class=\"fig-list\"><li>Wenn <code>[TRUE]</code>: Aufruf der Unterfunktion <code>E2E_P01_handle_wrongSequence</code>, anschließende Zuweisung <code>returnvalue = E2E_P01STATUS_WRONGSEQUENCE</code> und Verzweigung zum Ende (<code>return</code>).\n</li><li>Wenn <code>[FALSE]</code>: Ausführung von <code>returnvalue = E2E_P01_handle_ok_and_okSomeLost</code>.\n</li></ul>\n</li></ul>\n</li><li><strong>Abschluss</strong>: Alle Pfade werden zusammengeführt und die Aktivität terminiert mit <code>return</code>.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Auswerteverhalten für E2E Profile 1 Empfänger gemäß AUTOSAR PRS E2EProtocol. Software-Entwickler müssen sicherstellen, dass bei der Counter-Arithmetik der Wertebereich (4 Bit, Zyklus 0 bis 14) exakt mit der Offset-Korrektur <code>15 + ReceivedCounter - LastValidCounter</code> abgebildet wird. Die Unterfunktionen zur Zählerfortschreibung bei wiederholten Daten bzw. Sequenzfehlern müssen vor dem Setzen des jeweiligen Return-Status ausgeführt werden. Treten keine Wiederholungen oder übermäßigen Sprünge auf, ist zwingend die Routine <code>E2E_P01_handle_ok_and_okSomeLost</code> zur Auswertung regulärer bzw. verlustbehafteter Datenübertragungen zu durchlaufen.</p>"}], "trans": [{"from": "FIG-87a8b583b88e47d7", "to": "FIG-006103441fa3be3a", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
